def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid[:]]

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find contiguous non-background runs on each pair of opposite borders.
    def runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color = line[i]
            j = i
            while j + 1 < len(line) and line[j + 1] == color:
                j += 1
            if j > i:
                result.append((i, j, color))
            i = j + 1
        return result

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != bg]
    border_colors = set()
    horizontal = None
    vertical = None

    top, bottom = runs(grid[0]), runs(grid[-1])
    for a in top:
        for b in bottom:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                horizontal = (a, b)
                border_colors.add(a[2])
                break
        if horizontal:
            break

    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][-1] for r in range(h)])
    for a in left:
        for b in right:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                vertical = (a, b)
                border_colors.add(a[2])
                break
        if vertical:
            break

    marker_colors = [v for v in counts if v != bg and v not in border_colors]
    if not marker_colors:
        return out
    marker = min(marker_colors, key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker]

    def paint_ray(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == marker:
                out[r][c] = 4
                break
            out[r][c] = marker
            r += dr
            c += dc

    if horizontal:
        a, b = horizontal
        # Marker positions along the rail give offsets to project onto both rails.
        source = a if any(a[0] <= c <= a[1] for r, c in points) else b
        offsets = {c - source[0] for r, c in points
                   if source[0] <= c <= source[1]}
        for run, direction in ((a, 1), (b, -1)):
            for off in offsets:
                c = run[0] + off
                if c <= run[1]:
                    paint_ray(1 if direction == 1 else h - 2, c, direction, 0)

    if vertical:
        a, b = vertical
        source = a if any(a[0] <= r <= a[1] for r, c in points) else b
        offsets = {r - source[0] for r, c in points
                   if source[0] <= r <= source[1]}
        for run, direction in ((a, 1), (b, -1)):
            for off in offsets:
                r = run[0] + off
                if r <= run[1]:
                    paint_ray(r, 1 if direction == 1 else w - 2, 0, direction)

    return out
